// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address user = address(0xdead);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.addToBalance{value: 1 ether}();
        uint256 balance = c.getBalance(user);
        assertTrue(balance == 1 ether);
    }
}
